package tech.kayys.cifr.engine.action;

import tech.kayys.cifr.engine.task.TaskId;

import java.util.Map;
import java.util.Set;

/**
 * Structured action proposal generated by the reasoning model.
 * A proposal is merely data until authorized by policy and wrapped in an ExecutionTransaction.
 */
public record ActionProposal(
    String id,
    TaskId taskId,
    ActionType type,
    ActionTarget target,
    Map<String, Object> arguments,
    String reason,
    Set<String> supportingEvidenceIds,
    double confidence
) {
    public ActionProposal {
        arguments = arguments != null ? Map.copyOf(arguments) : Map.of();
        supportingEvidenceIds = supportingEvidenceIds != null ? Set.copyOf(supportingEvidenceIds) : Set.of();
    }

    public static ActionProposal of(String id, TaskId taskId, ActionType type, ActionTarget target, String reason) {
        return new ActionProposal(id, taskId, type, target, Map.of(), reason, Set.of(), 1.0);
    }
}
